package com.college.notes.controller;
import com.college.notes.dto.NoteDtos.NoteResponse; import com.college.notes.service.NoteService; import org.springframework.core.io.Resource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/notes") public class NoteController {private final NoteService service;public NoteController(NoteService s){service=s;} @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public NoteResponse upload(@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) Integer unit,@RequestParam Long subjectId,@RequestPart MultipartFile file){return service.upload(title,description,unit,subjectId,file);} @GetMapping public List<NoteResponse> list(@RequestParam(defaultValue="") String q,@RequestParam(required=false) Long subjectId){return service.visible(q,subjectId);} @GetMapping("/mine") public List<NoteResponse> mine(){return service.mine();} @GetMapping("/{id}/file") public ResponseEntity<Resource> file(@PathVariable Long id){Resource r=service.file(id);MediaType type=MediaTypeFactory.getMediaType(r).orElse(MediaType.APPLICATION_OCTET_STREAM);return ResponseEntity.ok().contentType(type).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+r.getFilename()+"\"").body(r);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
